/* MedicCare.module.css */

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000; /* darkened to meet 4.5:1 contrast with accent */
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  box-sizing: border-box;
  overflow-x: hidden;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

/* ---------- Navigation ---------- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 20px 15px;
}

.navToggle {
  display: none;
}

.navToggleLabel {
  display: none;
  cursor: pointer;
  padding: 10px;
}

.navToggleIcon {
  display: block;
  width: 30px;
  height: 2px;
  background: var(--vt-ink);
  position: relative;
  transition: background 0.3s;
}

.navToggleIcon::before,
.navToggleIcon::after {
  content: '';
  position: absolute;
  left: 0;
  width: 30px;
  height: 2px;
  background: var(--vt-ink);
  transition: top 0.3s, transform 0.3s;
}

.navToggleIcon::before {
  top: -8px;
}

.navToggleIcon::after {
  top: 8px;
}

.navToggle:checked + .navIn .navToggleIcon {
  background: transparent;
}

.navToggle:checked + .navIn .navToggleIcon::before {
  top: 0;
  transform: rotate(45deg);
}

.navToggle:checked + .navIn .navToggleIcon::after {
  top: 0;
  transform: rotate(-45deg);
}

.navLinks {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  align-items: center;
}

.navLinks a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  font-weight: 600;
  font-size: 1rem;
  padding: 0.5rem 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

.brandLink {
  text-decoration: none;
  margin-left: 0;
}

.brand {
  color: var(--vt-accent);
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
}

.brand strong {
  display: block;
  color: var(--vt-ink-soft);
  font-size: 0.75rem;
  font-weight: 400;
}

/* ---------- Hero ---------- */
.hero {
  padding-top: 94px; /* offset for fixed nav */
}

.heroContainer {
  position: relative;
  width: 100%;
  height: 580px;
  overflow: hidden;
}

.heroSlides {
  display: flex;
  height: 100%;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  z-index: 2;
}

.heroTitle {
  font-size: 3rem;
  line-height: 1.2;
  font-weight: 700;
  color: var(--vt-ink);
  margin: 0 0 0.5rem;
}

.heroPara {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin: 0 0 1.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.5rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  transition: all 0.3s;
  background: transparent;
  position: relative;
  overflow: hidden;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--vt-line);
  color: var(--vt-accent);
  text-align: center;
  transition: top 0.3s cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before,
.customLink:focus::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
}

/* ---------- About ---------- */
.about {
  padding: 7rem 0;
}

.container {
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.sectionTitle {
  text-align: center;
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 3rem;
}

.aboutText {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

/* ---------- Gallery ---------- */
.gallery {
  width: 100%;
  overflow: hidden;
}

.galleryContainer {
  width: 100%;
}

.galleryRow {
  display: flex;
  flex-wrap: nowrap;
  width: 100%;
}

.galleryItem {
  flex: 1 1 50%;
  margin: 0;
  padding: 0;
}

.galleryImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ---------- Timeline ---------- */
.timeline {
  padding: 7rem 0;
}

.timelineTrack {
  position: relative;
}

.timelineTrack::before {
  content: '';
  position: absolute;
  top: 37px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 85%;
  border-left: 1px solid var(--vt-line);
  z-index: 1;
}

.timelineNode {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  margin: 2rem 0;
  position: relative;
}

.timelineNode.even .timelineDate {
  order: 1;
  text-align: right;
}

.timelineNode.even .timelineIcon {
  order: 2;
}

.timelineNode.even .timelineContent {
  order: 3;
  text-align: left;
}

.timelineNode.odd .timelineDate {
  order: 3;
  text-align: left;
}

.timelineNode.odd .timelineIcon {
  order: 2;
}

.timelineNode.odd .timelineContent {
  order: 1;
  text-align: right;
}

.timelineDate {
  padding-top: 1rem;
  font-weight: 600;
  color: var(--vt-ink-soft);
}

.timelineIcon {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  margin: 0 20px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
}

.timelineIcon i {
  font-size: 2rem;
  color: var(--vt-accent);
}

.timelineContent {
  background: var(--vt-surface);
  border-radius: 0 0 0.25rem 0.25rem;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  position: relative;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 0.75rem 1.5rem;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineContent p {
  padding: 1rem 1.5rem;
  color: var(--vt-ink-soft);
  margin: 0;
}

.timelineNode.odd .timelineContent h3::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even .timelineContent h3::after {
  content: '';
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* ---------- Footer ---------- */
.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerCol {
  flex: 1;
  min-width: 200px;
}

.footerCol h5 {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
}

.footerCol p {
  color: var(--vt-ink-soft);
  margin: 0.5rem 0;
}

.footerCol a {
  color: var(--vt-accent);
  text-decoration: none;
}

.footerCol a:hover {
  text-decoration: underline;
}

.socialLinks {
  display: flex;
  gap: 1rem;
}

.socialLinks a {
  color: var(--vt-ink-soft);
  font-size: 1.25rem;
  transition: color 0.3s;
}

.socialLinks a:hover {
  color: var(--vt-accent);
}

.copyright {
  margin-top: 3rem;
  text-align: center;
  color: var(--vt-ink-soft);
  font-size: 0.875rem;
}

/* ---------- Focus visible ---------- */
.root a:focus-visible,
.root button:focus-visible,
.root input:focus-visible,
.root label:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* ---------- Media Queries ---------- */
@media screen and (min-width: 1600px) {
  .heroContainer {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .nav {
    padding: 10px 0;
  }

  .navIn {
    flex-wrap: wrap;
    padding: 0 15px;
  }

  .navToggleLabel {
    display: block;
    order: 1;
  }

  .navLinks {
    display: none;
    width: 100%;
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
    padding: 1rem 0;
  }

  .navToggle:checked + .navIn .navLinks {
    display: flex;
  }

  .brandLink {
    order: 2;
    margin-left: auto;
  }

  .brand {
    font-size: 1.25rem;
  }

  .hero {
    padding-top: 74px;
  }

  .heroContainer {
    height: auto;
  }

  .heroSlides {
    display: block;
    overflow-x: visible;
  }

  .heroSlide {
    min-width: auto;
    height: auto;
  }

  .heroImage {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: 0;
    right: 0;
    width: 100%;
    margin-top: -100px;
    padding: 2rem;
  }

  .heroTitle {
    font-size: 2.25rem;
  }

  .container {
    max-width: 720px;
  }

  .about {
    padding: 5rem 0;
  }

  .timeline {
    padding: 5rem 0;
  }

  .timelineNode {
    grid-template-columns: auto 1fr;
    gap: 1rem;
    margin: 1.5rem 0;
  }

  .timelineTrack::before {
    left: 30px;
    top: 60px;
    height: 90%;
  }

  .timelineNode.even .timelineDate,
  .timelineNode.odd .timelineDate {
    order: 1;
    text-align: left;
    grid-column: 1 / -1;
    padding-top: 0;
  }

  .timelineNode.even .timelineIcon,
  .timelineNode.odd .timelineIcon {
    order: 2;
    grid-column: 1 / 2;
    grid-row: 2 / 3;
    margin: 0;
  }

  .timelineNode.even .timelineContent,
  .timelineNode.odd .timelineContent {
    order: 3;
    grid-column: 2 / 3;
    grid-row: 2 / 3;
    text-align: left;
  }

  .timelineNode.even .timelineContent h3::after,
  .timelineNode.odd .timelineContent h3::after {
    display: none;
  }

  .footerRow {
    flex-direction: column;
    gap: 2rem;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
    margin-top: -80px;
  }

  .heroTitle {
    font-size: 1.75rem;
  }

  .container {
    padding: 0 15px;
  }

  .galleryRow {
    flex-direction: row; /* keep side by side on mobile like original */
  }
}

@media screen and (max-width: 575px) {
  .timelineTrack::before {
    left: 25px;
  }

  .timelineNode {
    grid-template-columns: 50px 1fr;
    gap: 0.5rem;
  }

  .timelineIcon {
    width: 50px;
    height: 50px;
  }

  .timelineIcon i {
    font-size: 1.5rem;
  }
}

@media screen and (max-width: 480px) {
  .heroLinks {
    gap: 1rem;
  }

  .customLink {
    font-size: 0.75rem;
    line-height: 30px;
    padding: 0 20px;
  }

  .contactPhone {
    font-size: 0.75rem;
  }
}

@media screen and (max-width: 360px) {
  .timelineTrack::before {
    left: 20px;
  }
}
